INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G6-GEO-006', 'ru-KZ', 'plaintext', 'Найдите расстояние между точками {{p1}} и {{p2}}, расположенными на одной координатной оси.', '1.0.0-draft'),
    ('G6-GEO-007', 'ru-KZ', 'plaintext', 'В какой четверти координатной плоскости находится точка ({{x}}, {{y}})?', '1.0.0-draft'),
    ('G6-GEO-008', 'ru-KZ', 'plaintext', 'Основание треугольника равно {{b}}, а высота — {{h}}. Найдите площадь треугольника.', '1.0.0-draft'),
    ('G6-GEO-009', 'ru-KZ', 'plaintext', 'Основание параллелограмма равно {{b}}, а высота — {{h}}. Найдите его площадь.', '1.0.0-draft'),
    ('G6-GEO-010', 'ru-KZ', 'plaintext', 'Фигура состоит из прямоугольника размером {{a}} × {{b}} и треугольника с основанием {{b}} и высотой {{h}}. Найдите общую площадь.', '1.0.0-draft'),
    ('G6-GEO-011', 'ru-KZ', 'plaintext', 'Измерения прямоугольной призмы равны {{a}}/2, {{b}}/2 и {{c}}/2. Найдите её объём.', '1.0.0-draft'),
    ('G6-GEO-012', 'ru-KZ', 'plaintext', 'Измерения прямоугольной призмы равны {{a}}, {{b}} и {{c}}. Найдите площадь её полной поверхности.', '1.0.0-draft'),
    ('G6-GEO-013', 'ru-KZ', 'plaintext', 'У треугольной призмы основание треугольника равно {{b}}, его высота равна {{h}}, а длина призмы равна {{l}}. Найдите площадь поверхности.', '1.0.0-draft'),
    ('G6-GEO-014', 'ru-KZ', 'plaintext', 'Развёртка состоит из следующих граней: {{faces}}. Какое геометрическое тело можно из неё собрать?', '1.0.0-draft'),
    ('G6-GEO-015', 'ru-KZ', 'plaintext', 'Вершины прямоугольника имеют координаты (0, 0), ({{a}}, 0), ({{a}}, {{b}}), (0, {{b}}). Найдите его площадь.', '1.0.0-draft')
